void recspl(uint64_t pc,const State&c,int i,int rem,State&a,int e,J &L){if(i==12){if(rem)return;State b{};for(int k=0;k<12;k++)b[k]=c[k]-a[k];uint64_t pa=pack(a),pb=pack(b);if(pa>pb)return;splitcount++;uint64_t ca=canon(a),cb=canon(b);double d=dlt(pa,pb,pc),q=ldexp(1.0,e);J energy={-beta0*q*d,-q*d,0.0,0.0,0.0}, term;if(pa!=pb) term=add(energy,add(solve(ca,e+1),solve(cb,e+1)));else {J x=scale(solve(ca,e+1),2.0), y=solve(ca,e+2);term=add(energy,logadd(x,y));term.v-=log(2.0);}L=logadd(L,term);return;}int tail=0;for(int k=i+1;k<12;k++)tail+=c[k];for(int v=max(0,rem-tail);v<=min<int>(c[i],rem);v++){a[i]=v;recspl(pc,c,i+1,rem-v,a,e,L);}a[i]=0;}
